def executar(raiz, rotulo, comando, ambiente, relatorio):
    relatorio["etapa"] = rotulo
    print("Executando " + rotulo + "...", flush=True)
    r = subprocess.run(comando, cwd=raiz, env=ambiente, capture_output=True, text=True, encoding="utf-8", errors="replace")
    saida = r.stdout + r.stderr
    print(saida, end="" if saida.endswith("\n") else "\n", flush=True)
    relatorio[rotulo] = {"return_code": r.returncode, "saida": saida}
    print(rotulo.upper() + "_RETURN_CODE=" + str(r.returncode), flush=True)
    if r.returncode: raise RuntimeError("A etapa " + rotulo + " falhou; confira o relatório.")


def salvar_relatorio(raiz: Path, relatorio):
    conteudo = json.dumps(relatorio, ensure_ascii=False, indent=2) + "\n"
    for extensao in ("json", "txt"):
        alvo = seguro(raiz, STEM + "." + extensao)
        with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", newline="\n", dir=raiz, delete=False, prefix="mec_d31_relatorio_") as temp:
            temp.write(conteudo); caminho = Path(temp.name)
        try: os.replace(caminho, alvo)
        finally: caminho.unlink(missing_ok=True)
        print(("JSON=" if extensao == "json" else "RELATORIO=") + str(alvo), flush=True)


def main() -> int:
    print("MEC-Serviços D31 — Intermediação Administrativa", flush=True); print("REVISION=" + REVISION, flush=True)
    raiz = None; originais = {}; alterados = []; pastas_novas = []; backup = None
    dist_existia = False; build_iniciado = False; schema_concluido = False
    relatorio = {"revision": REVISION, "resultado": "ERRO", "etapa": "inicio", "restaurado": False,
                 "contato_direto_permitido": False, "registros_anteriores_recriados": False}
    try:
        if sys.version_info < (3, 11): raise RuntimeError("Use a .venv com Python 3.11 ou mais recente.")
        raiz = localizar_raiz(); print("ROOT=" + str(raiz), flush=True)
        urls = executar_git(raiz, "remote", "get-url", "--all", "origin").splitlines()
        if not urls or not all(origem_mec(u) for u in urls): raise RuntimeError("Origin não corresponde ao projeto MEC-Servicos.")
        print("ORIGIN_MEC_CONFIRMADO=True", flush=True)
        exigir_backend_parado()
        if executar_git(raiz, "ls-files", "--", "data/mec_acessos.db*", "data/MEC_SERVICOS_D30_ACESSOS_INICIAIS*.txt"):
            raise RuntimeError("Arquivo privado de acesso rastreado no Git; preserve-o localmente e retire-o do índice.")
        relatorio["etapa"] = "conferir_base"
        plano = plano_arquivos(raiz)
        pacote = json.loads(seguro(raiz, "frontend/package.json").read_text(encoding="utf-8-sig"))
        if not pacote.get("scripts", {}).get("build") or "axios" not in pacote.get("dependencies", {}):
            raise RuntimeError("Confira build e Axios no frontend.")
        npm = shutil.which("npm.cmd" if os.name == "nt" else "npm")
        if not npm: raise RuntimeError("npm não encontrado.")
        os.chdir(raiz)
        banco, acesso = configuracao_bancos(raiz); antes = ler_historico(banco); hash_acesso = sha(acesso.read_bytes())
        with closing(sqlite3.connect(banco.as_uri() + "?mode=ro", uri=True)) as c:
            c.execute("PRAGMA query_only=ON"); conferir_schema(c)
        print("BASE_D30_E_ACESSOS_OK=True", flush=True)
        relatorio["etapa"] = "backup"
        backup = seguro(raiz, "_mec_backups/D31_INTERMEDIACAO_ADMIN_" + datetime.now().strftime("%Y%m%d_%H%M%S_%f"))
        if subprocess.run([shutil.which("git"), "check-ignore", str(backup / "banco_negocio_antes.db")], cwd=raiz, capture_output=True).returncode:
            raise RuntimeError("A pasta _mec_backups precisa estar ignorada no Git antes de criar o backup do banco.")
        backup.mkdir(parents=True); relatorio["backup"] = str(backup); print("BACKUP_DIR=" + str(backup), flush=True)
        with closing(sqlite3.connect(banco.as_uri() + "?mode=ro", uri=True)) as origem, closing(sqlite3.connect(backup / "banco_negocio_antes.db")) as destino:
            origem.backup(destino)
        dist = seguro(raiz, "frontend/dist"); dist_existia = dist.exists()
        if dist_existia: shutil.copytree(dist, backup / "frontend_dist")
        for nome in plano:
            alvo = raiz / nome; originais[nome] = alvo.read_bytes() if alvo.exists() else None
            if originais[nome] is not None:
                copia = backup / "originais" / nome; copia.parent.mkdir(parents=True, exist_ok=True); copia.write_bytes(originais[nome])
            for pasta in alvo.parents:
                if pasta == raiz: break
                if not pasta.exists() and pasta not in pastas_novas: pastas_novas.append(pasta)
        (backup / "MANIFESTO.json").write_text(json.dumps({n: None if b is None else sha(b) for n, b in originais.items()}, indent=2) + "\n", encoding="utf-8")
        relatorio["etapa"] = "aplicar_fontes"
        for nome, conteudo in plano.items():
            alvo = raiz / nome; alvo.parent.mkdir(parents=True, exist_ok=True); alterados.append(nome); alvo.write_bytes(conteudo)
        print("ARQUIVOS_D31_APLICADOS=" + str(len(plano)), flush=True)
        with tempfile.TemporaryDirectory(prefix="mec_d31_testes_") as pasta:
            ambiente = dict(os.environ)
            ambiente["MEC_URL_BANCO_DADOS"] = "sqlite:///" + (Path(pasta) / "negocio.db").resolve().as_posix()
            ambiente["MEC_ACESSOS_DB"] = str(Path(pasta) / "acesso.db")
            executar(raiz, "validacao_rotas", [sys.executable, "-c", VALIDAR_ROTAS], ambiente, relatorio)
            executar(raiz, "pytest", [sys.executable, "-m", "pytest", "tests", "-q", "--ignore=tests/mold"], ambiente, relatorio)
            build_iniciado = True
            executar(raiz / "frontend", "npm_build", [npm, "run", "build"], ambiente, relatorio)
        if sha(acesso.read_bytes()) != hash_acesso: raise RuntimeError("O banco de acesso mudou durante a instalação; nenhum acesso será sobrescrito.")
        relatorio["etapa"] = "preparar_tabelas"
        criadas = preparar_tabelas(banco, antes); schema_concluido = True
        relatorio.update({"resultado": "OK", "etapa": "concluido", "painel_administrativo_implantado": True,
            "tabelas_criadas": criadas, "arquivos_alterados": alterados, "historico_anterior_preservado": True,
            "contas_e_senhas_preservadas": True, "novo_fluxo": "lote_completo_por_ordem", "historico_tabelas_sha256": antes})
        print("TABELAS_D31_CRIADAS=" + str(criadas), flush=True)
        print("HISTORICO_ANTERIOR_PRESERVADO=True", flush=True); print("CONTAS_E_SENHAS_PRESERVADAS=True", flush=True)
        try: salvar_relatorio(raiz, relatorio)
        except OSError: print("RELATORIO_NAO_GRAVADO=True; instalação concluída, preserve a saída do terminal.", flush=True)
        print("RESULTADO=OK", flush=True)
        print("Reinicie backend e frontend. Entre como administrador e abra /admin/intermediacao.", flush=True)
        print("Ordens anteriores concluídas permanecem no histórico. Inicie o ciclo em uma ordem aberta/em execução com contratação ativa.", flush=True)
        print("Cliente e fornecedor consultam o andamento em Entregas; as movimentações e decisões são administrativas.", flush=True)
        return 0
    except Exception as erro:
        relatorio["erro"] = str(erro); print("ETAPA=" + relatorio["etapa"], flush=True); print("ERRO=" + str(erro), flush=True)
        if raiz and alterados and not schema_concluido:
            falhas = []
            for nome in reversed(alterados):
                try:
                    if originais[nome] is None: (raiz / nome).unlink(missing_ok=True)
                    else: (raiz / nome).write_bytes(originais[nome])
                except OSError as falha: falhas.append(str(falha))
            if build_iniciado:
                try:
                    if dist.exists(): shutil.rmtree(dist)
                    if dist_existia: shutil.copytree(backup / "frontend_dist", dist)
                except OSError as falha: falhas.append(str(falha))
            for p in sorted(pastas_novas, key=lambda p: len(p.parts), reverse=True):
                try:
                    if p.exists() and not any(p.iterdir()): p.rmdir()
                except OSError as falha: falhas.append(str(falha))
            relatorio["restaurado"] = not falhas
            if falhas: relatorio["falhas_restauracao"] = falhas
            print("RESTAURADO=" + str(relatorio["restaurado"]), flush=True)
        if raiz:
            try: salvar_relatorio(raiz, relatorio)
            except OSError: print("RELATORIO_NAO_GRAVADO=True", flush=True)
        print("RESULTADO=ERRO", flush=True)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
